/* Dossier presentation only. Catalog calculations and character persistence stay in V2/app. */
window.ND_DOSSIER=(()=>{
 const states=new Map();let currentKey=null;
 const V=()=>window.ND_CATALOG_V2;
 const sign=n=>n<0?'−'+Math.abs(n):'+'+n;
 function state(){const key=cloudRecord?.id||'local';if(!states.has(key)){const mobile=window.matchMedia?.('(max-width: 899px)').matches??false;states.set(key,{open:{attributes:!mobile,skills:!mobile,weapons:!mobile,perks:!mobile,bio:false},filter:'mastered',editing:null,info:{}});}currentKey=key;return states.get(key);}
 function remember(){if(!currentKey||!states.has(currentKey))return;const s=states.get(currentKey);document.querySelectorAll('[data-dossier-open]').forEach(el=>s.open[el.dataset.dossierOpen]=el.open);document.querySelectorAll('[data-dossier-info]').forEach(el=>s.info[el.dataset.dossierInfo]=el.open);}
 function module(id,title,meta,body){return `<details class="dossier-module dossier-${id}" data-dossier-open="${id}" ${state().open[id]?'open':''}><summary><span>${title}</span><small>${esc(meta)}</small><b aria-hidden="true">+</b></summary><div class="dossier-module-body">${body}</div></details>`;}
 function sources(stat){return stat.sources?.length?`<ul class="dossier-sources">${stat.sources.map(s=>`<li>${esc(s.name)} <b>${sign(s.value)}</b></li>`).join('')}</ul>`:'';}
 function stat(type,i){return window.ND_SHEET_V2.stat(type,i);}
 function values(type,i){const x=stat(type,i),editing=state().editing===type;return `<div class="dossier-values"><span class="dossier-base" title="Базовое значение">${editing?selector(type+'.'+i,x.base,type==='attributes'?[0,1,2]:[0,1,2,3],(type==='attributes'?D.attributes:D.skills)[i].name):x.base}</span>${x.permanentBonus?`<span class="dossier-bonus" title="Постоянный бонус снаряжения">${sign(x.permanentBonus)}</span>`:'<span class="dossier-zero" aria-hidden="true">—</span>'}<strong class="dossier-effective" aria-label="Итого ${x.effective}"><small>=</small> ${x.effective}</strong></div>`;}
 function editButton(type){return canEdit?`<button type="button" class="dossier-edit-values" data-dossier-edit="${type}" aria-pressed="${state().editing===type}">${state().editing===type?'Готово':'Изменить базу'}</button>`:'';}
 function info(type,i,name,description){const id=type+'-'+i;return `<details class="dossier-info" data-dossier-info="${id}" ${state().info[id]?'open':''}><summary>${esc(name)}<span aria-hidden="true">ⓘ</span></summary><div><p>${esc(description)}</p>${sources(stat(type,i))}</div></details>`;}
 function attributes(){return module('attributes','Характеристики','04',`<div class="dossier-section-tools"><span>База <i>Бонус</i> Итог</span>${editButton('attributes')}</div><div class="dossier-stat-table">${D.attributes.map((a,i)=>`<div class="dossier-stat-row"><span class="dossier-row-index">0${i+1}</span>${info('attributes',i,a.name,a.description)}${values('attributes',i)}</div>`).join('')}</div>`);}
 function skills(){const s=state(),rows=D.skills.map((x,i)=>({x,i,stat:stat('skills',i)})).filter(x=>s.filter==='all'||x.stat.base>0||x.stat.permanentBonus!==0);return module('skills','Навыки',String(D.skills.length),`<div class="dossier-section-tools"><div class="dossier-skill-filters" role="group" aria-label="Показать навыки"><button data-dossier-filter="mastered" aria-pressed="${s.filter==='mastered'}">Освоенные</button><button data-dossier-filter="all" aria-pressed="${s.filter==='all'}">Все</button></div>${editButton('skills')}</div><div class="dossier-skill-table">${rows.map(({x,i,stat:v})=>`<div class="dossier-skill-row">${info('skills',i,x.name,x.description)}<span class="dossier-rank" aria-label="Базовый ранг ${v.base} из 3">${[1,2,3].map(n=>`<i class="${n<=v.base?'filled':''}"></i>`).join('')}</span>${values('skills',i)}</div>`).join('')||'<p class="dossier-empty">Освоенных навыков пока нет</p>'}</div><p class="dossier-budget">Свободные очки: <b>${E.derive(card,D.catalog).skillPoints}</b></p>`);}
 function owned(){const normalized=V().normalizeCharacter(card,D.catalog);return normalized.equipmentItems.map(instance=>({instance,item:V().resolve(D.catalog,instance.catalogId)||instance.snapshot})).filter(x=>x.item&&x.instance.quantity>0);}
 function icon(item){return (typeof catalogIcon==='function'?catalogIcon(item,'dossier-item-icon'):'')||'<span class="dossier-icon-placeholder" aria-hidden="true"><svg viewBox="0 0 32 32" fill="none" stroke="currentColor"><path d="M5 9h22v14H5z M11 9V5h10v4 M5 15h22 M14 15v4h4v-4"/></svg></span>';}
 function rules(item){return `<details class="dossier-item-rules"><summary>Описание и особые правила</summary><p>${esc(item.description||'Описание не задано')}</p>${item.rulesText&&item.rulesText!==item.description?`<p>${esc(item.rulesText)}</p>`:''}</details>`;}
 function weapons(){const rows=owned().filter(({instance:x,item})=>x.location==='equipped'&&x.equipped!==false&&['ranged_weapon','melee_weapon'].includes(item.classId));return module('weapons','Активное оружие',String(rows.length),`${rows.map(({item})=>{const x=item.stats||{},range=item.classId==='melee_weapon'?(x.reach??item.range):(x.rangeMin!=null||x.rangeMax!=null?`${x.rangeMin??'?'}–${x.rangeMax??'?'}`:item.range);return `<article class="dossier-weapon-preview"><div class="dossier-item-heading">${icon(item)}<div><span class="dossier-item-status">Экипировано</span><h3>${esc(item.displayName||item.name)}</h3></div></div><dl class="dossier-weapon-stats"><div><dt>Урон</dt><dd>${esc(x.damage??item.damage??'—')}</dd></div><div><dt>${item.classId==='melee_weapon'?'Досягаемость':'Дальность'}</dt><dd>${esc(range??'—')}</dd></div><div><dt>Хват</dt><dd>${esc(x.hands!=null?x.hands===1?'1 рука':'2 руки':item.slot??'—')}</dd></div></dl>${rules(item)}</article>`;}).join('')||'<p class="dossier-empty">Оружие не экипировано</p>'}<button class="dossier-manage" data-dossier-gear>Управлять снаряжением ↗</button>`);}
 function perks(){const rows=owned().filter(({instance:x,item})=>item.classId==='perk'&&(x.location==='learned'||x.metadata?.learned===true));return module('perks','Перки и способности',String(rows.length),`<div class="dossier-perk-list">${rows.map(({item})=>{const text=item.description||item.rulesText||'',activation=item.equipment?.activation;return `<article class="dossier-perk"><span class="dossier-item-status">${activation==='active'?'Активный':activation==='passive'?'Пассивный':'Тип не указан'}</span><h3>${esc(item.displayName||item.name)}</h3><p>${esc(text.length>170?text.slice(0,167)+'…':text)}</p>${rules(item)}</article>`;}).join('')||'<p class="dossier-empty">Изученных перков пока нет</p>'}</div>`);}
 function adjust(kind,value,max){return `<div class="dossier-resource-controls"><button data-pip="${kind}" data-value="${Math.max(0,value-1)}" aria-label="${kind==='hp'?'Уменьшить здоровье':'Уменьшить защиту'}" ${value<=0?'disabled':''}>−</button><span class="dossier-resource-track" aria-hidden="true"><i style="width:${max>0?Math.max(0,Math.min(100,value/max*100)):0}%"></i></span><button data-pip="${kind}" data-value="${Math.min(max,value+1)}" aria-label="${kind==='hp'?'Увеличить здоровье':'Восстановить защиту'}" ${value>=max?'disabled':''}>+</button></div>`;}
 function metrics(){const d=E.derive(card,D.catalog),armor=owned().filter(({instance:x,item})=>x.location==='equipped'&&x.equipped!==false&&item.classId==='clothing_armor').sort((a,b)=>(b.item.stats?.armor||0)-(a.item.stats?.armor||0))[0]?.item;return `<div class="metrics dossier-metrics"><section class="dossier-metric dossier-health"><h2>Здоровье</h2><div class="dossier-metric-number">${card.hp}<small>/ ${d.maxHP}</small></div>${adjust('hp',card.hp,d.maxHP)}</section><section class="dossier-metric"><h2>Активная защита</h2><div class="dossier-metric-number">${d.currentArmor}<small>/ ${d.armor}</small></div><p class="dossier-armor-name">${esc(armor?.displayName||armor?.name||'Без брони')}</p>${d.armor?adjust('armor',d.currentArmor,d.armor):''}</section><section class="dossier-metric"><h2>Хром</h2><div class="dossier-metric-number">${d.used}<small>/ ${d.capacity}</small></div><p class="${d.freeChrome<0?'warning':''}">${d.freeChrome>=0?'Свободно: '+d.freeChrome:'Превышение: '+(-d.freeChrome)}</p></section><section class="dossier-metric dossier-experience"><h2><label for="experience-value">Опыт</label></h2><input id="experience-value" data-path="experience" type="number" min="0" step="1" inputmode="numeric" value="${card.experience??0}" aria-label="Очки опыта"><button id="spend-experience" ${!canEdit||!E.canSpendExperience(card)?'disabled':''}>Потратить ↗</button><span id="experience-hint" class="dossier-xp-hint">${E.canSpendExperience(card)?'Доступно развитие':'Нужно минимум 3 очка'}</span></section></div>`;}
 function identity(){return `<aside class="dossier-sidebar" aria-label="Личное дело"><div class="dossier-file-label">Personal file <span>${canEdit?'Редактирование':'Просмотр'}</span></div><div class="dossier-person"><div class="dossier-portrait">${card.photo?`<img src="${esc(card.photo)}" alt="Портрет персонажа">`:'<svg class="dossier-silhouette" viewBox="0 0 100 120" aria-label="Портрет не добавлен" role="img"><circle cx="50" cy="35" r="22"/><path d="M10 115v-22c0-35 80-35 80 0v22Z"/></svg>'}${canEdit?'<button id="edit-photo" aria-label="Изменить фото персонажа">Изменить фото</button>':''}</div><div class="dossier-identity"><h2 class="dossier-nickname">${esc(card.nickname||'Без псевдонима')}</h2><dl><div><dt>Имя</dt><dd>${esc(card.name||'Не указано')}</dd></div><div><dt>Возраст</dt><dd>${esc(card.age||'Не указан')}</dd></div></dl>${canEdit?'<button id="dossier-edit-identity">Редактировать</button>':''}</div></div><details class="dossier-bio" data-dossier-open="bio" ${state().open.bio?'open':''}><summary>Краткая история</summary><p>${esc(card.bio||'История ещё не написана')}</p>${canEdit?'<button id="dossier-edit-bio">Изменить историю</button>':''}</details></aside>`;}
 function render(){state();return `<div class="dossier-layout">${identity()}<div class="dossier-main"><div class="dossier-data-label">Character data</div>${metrics()}<div class="dossier-details-grid">${attributes()}${skills()}</div><div class="dossier-loadout-grid">${weapons()}${perks()}</div></div></div>`;}
 function editIdentity(bio=false){if(!canEdit)return;modal(bio?'Краткая история':'Идентификация',`<form id="dossier-identity-form">${bio?`<label class="field">История<textarea name="bio" rows="7" maxlength="20000">${esc(card.bio)}</textarea></label>`:`<label class="field">Никнейм<input name="nickname" maxlength="20000" value="${esc(card.nickname)}"></label><label class="field">Имя персонажа<input name="name" maxlength="20000" value="${esc(card.name)}"></label><label class="field">Возраст<input name="age" maxlength="20000" value="${esc(card.age)}"></label>`}<button class="yellow" type="submit">Сохранить</button></form>`);$('#dossier-identity-form').onsubmit=e=>{e.preventDefault();if(!canEdit)return;try{const fields=bio?['bio']:['nickname','name','age'],next=E.clone(card);fields.forEach(k=>next[k]=e.currentTarget.elements[k].value);E.validate(next,D);fields.forEach(k=>card[k]=next[k]);changed();closeModal();window.ND_DOSSIER.remember();window.ND_DOSSIER.refresh();}catch(err){error(err);}};}
 function bind(){const boundState=state();document.querySelectorAll('[data-dossier-open]').forEach(el=>el.ontoggle=()=>{boundState.open[el.dataset.dossierOpen]=el.open;});document.querySelectorAll('[data-dossier-info]').forEach(el=>el.ontoggle=()=>{boundState.info[el.dataset.dossierInfo]=el.open;});document.querySelectorAll('[data-dossier-filter]').forEach(b=>b.onclick=()=>{remember();state().filter=b.dataset.dossierFilter;refresh();});document.querySelectorAll('[data-dossier-edit]').forEach(b=>b.onclick=()=>{if(!canEdit)return;remember();const s=state();s.editing=s.editing===b.dataset.dossierEdit?null:b.dataset.dossierEdit;if(s.editing==='skills')s.filter='all';refresh();});document.querySelectorAll('[data-dossier-gear]').forEach(b=>b.onclick=()=>switchSheetTab('inventory'));if($('#dossier-edit-identity'))$('#dossier-edit-identity').onclick=()=>editIdentity();if($('#dossier-edit-bio'))$('#dossier-edit-bio').onclick=()=>editIdentity(true);}
 // Alias avoids shadowing the application render function inside this module.
 function refresh(){renderCharacterSheet();}
 return {render,remember,bind,refresh};
})();
